import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

/** A sheet's holiday as the store holds it: a date (YYYY-MM-DD), on the sheet at most once. A claim's due-by,
 *  fixed when it is added, is moved past the holidays on the sheet then to the next day that is not one. */
export type Holiday = { id: number; date: string };

export const holidaysQueryKey = (sheetId: string) => ['sheet', sheetId, 'holidays'] as const;

export const holidaysPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/holidays`;

/** The sheet's holidays, by date. */
export function useHolidays() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: holidaysQueryKey(sheet ?? ''),
    queryFn: () => getJson<Holiday[]>(holidaysPath(sheet ?? '')),
    enabled: !!sheet,
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { holidaysPath, holidaysQueryKey, useHolidays, type Holiday } from './holidays';

// The sheet's holidays, and the entry that adds one. A date that is not a calendar date, or one already on the
// list, is refused by the server and shows the error beside the entry, which goes as soon as the entry changes.
function Holidays() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const holidays = useHolidays();
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();
  const add = useMutation({
    mutationFn: (body: { date: string }) => postJson<Holiday>(holidaysPath(sheet ?? ''), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: holidaysQueryKey(sheet ?? '') });
      setDate('');
    },
  });
  const submit = useSubmitOnce(add);

  if (!user || !sheet) return null;
  return (
    <section data-testid="holidays">
      <h2>Holidays</h2>
      <ul>
        {(holidays.data ?? []).map((h) => (
          <li key={h.id} data-testid={`holiday-row-${h.date}`}>{h.date}</li>
        ))}
      </ul>
      <form
        data-testid="holiday-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ date });
        }}
      >
        <input
          data-testid="holiday-date"
          placeholder="Date (YYYY-MM-DD)"
          value={date}
          onChange={(e) => { setDate(e.target.value); add.reset(); }}
        />
        <button type="submit" data-testid="holiday-add" disabled={add.isPending}>
          Add holiday
        </button>
        {add.isError && (
          <span data-testid="holiday-error">A holiday must be a calendar date not already on the list.</span>
        )}
      </form>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 6.5, Component: Holidays });
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { GRADES, gradeOn, usePeople } from '../people/people';
import { useClaims } from '../claims/claims';
import { personDue } from '../rates/due.slot';
import { sumDue, useRates } from '../rates/rates';
import { useSettings } from '../roles/roles';
import { periodDue, usePeriods } from '../periods/periods';
import { isActive } from '../claims/active.slot';

/** The statuses the summary counts claims by. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const;

// The summary panel, figured the same way as the list: per grade, how many people not retired have it in force on
// the sheet's today, their due-totals added up (skipping n/a) and how many of them are active; per period, its due-total; per status, how
// many of the sheet's claims have it.
function Summary() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const periods = usePeriods();
  const settings = useSettings();
  const today = useSheetToday();
  if (!user || !sheet) return null;
  const current = (people.data ?? []).filter((p) => p.retiredFrom === null);
  const allClaims = claims.data ?? [];
  return (
    <section data-testid="summary">
      <h2>Summary</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
            <th>Active</th>
          </tr>
        </thead>
