import { useQuery } from '@tanstack/react-query';
import { useNavigate } from '@tanstack/react-router';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { settingOn, type Settings } from '../roles/roles';
import { asString, useSearchParam } from '../../url/useSearchParam';

/** A claim's status: DRAFT to start, then OPEN and SETTLED; a clerk settling one above the clerk limit leaves it
 *  PENDING, until a steward approves it (SETTLED) or rejects it (OPEN again); a DRAFT, OPEN or PENDING claim can be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A claim as the store holds it: the amount with two decimals, the date (YYYY-MM-DD), the note, the status and
 *  the number given when it was opened (the sheet's next, or the next in its period: P1-1, X-1; null for a claim never opened; a voided claim keeps it) and the due fixed when it was
 *  settled (null when it has none: its due is live), and who opened it (null when never opened); whether its person's last statement binds it, and the
 *  figure it binds it to (null: n/a); the number of the settled claim of the same person it corrects (null when it is not
 *  a correction — a correction is a claim with a negative amount); the date its rounding goes by (a correction's is the
 *  date of the claim it corrects, else its own). */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  roundsOn: string;
  /** Its due-by (YYYY-MM-DD): the business day its terms (fixed when it was created) count to after its date then, past the holidays now. */
  dueBy: string;
  /** Its status log, oldest first: one line per status it has had, `<STATUS> by <user> on <date> due=<due>`. */
  log: string[];
  /** The date it is deferred until (YYYY-MM-DD), or null when it was never deferred. */
  deferredUntil: string | null;
  /** How many proofs it has: raised by one at a time (not on a SETTLED or VOID claim). */
  proofs: number;
  /** The number of the claim it was split off from, or null when it was not made by a split. */
  splitFrom: string | null;
  /** Whether it was added while the period its due-by falls in was soft-closed. */
  lateEntry: boolean;
  remindedOn: string | null;
  /** Its external reference, trimmed (unique on the sheet, ignoring case), or null when it has none. */
  ref: string | null;
  /** Its tags, trimmed, lower-cased and sorted, without repeats; empty when it has none. */
  tags: string[];
  /** Every tag it has ever carried, sorted: the sheet's tags are those of all its claims. */
  tagsUsed: string[];
};

/** Whether a claim is open: OPEN or PENDING (it goes overdue, and a hold takes it out of the live totals). */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/** Whether a claim shows and totals the figure its person's last statement bound it to: it is bound and not PENDING
 *  (a PENDING claim shows its live figure, and is bound again if rejected). */
export const isBound = (c: Claim) => c.stated && c.status !== 'PENDING';

/** Whether a claim is deferred on the sheet's today: it is OPEN and deferred until a date after it. Until then it
 *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
export const isDeferred = (c: Claim, today: string | undefined) =>
  c.status === 'OPEN' && c.deferredUntil !== null && today !== undefined && today < c.deferredUntil;

/** Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED claims do, but not a
 *  deferred one. */
export const counts = (c: Claim, today: string | undefined) => (isOpen(c) || c.status === 'SETTLED') && !isDeferred(c, today);

/** A hold: from a date on, to a date (YYYY-MM-DD, inclusive; null: open-ended). */
export type Hold = { from: string; to: string | null };

/** Each person's holds, and the date they are retired from (null: not retired), by person id. */
export type Holds = Map<number, { holds: Hold[]; retiredFrom: string | null }>;

/** The holds and retirement dates of the people, by person id. */
export const holdsOf = (people: { id: number; holds: Hold[]; retiredFrom?: string | null }[] | undefined): Holds =>
  new Map((people ?? []).map((p) => [p.id, { holds: p.holds, retiredFrom: p.retiredFrom ?? null }]));

/** Whether the claim's person has its OPEN and PENDING claims out of the live totals on the sheet's today: a hold
 *  of theirs covers its date, or their retirement date is reached (today on or after it). */
// closed period, shows the claim's error instead of opening its editor (an open claim is voided and added anew). Opening a
// DRAFT's editor locks the claim for other users until it is saved or cancelled, or the sheet's today changes: another
// user's edit button on a locked claim (and a viewer's) shows the claim's error, and their editor cannot save. A DRAFT's
// amount can also be saved in the row (the amount typed beside the edit button), by the claim form's rules: a refusal
// shows the claim's error. A role the permission matrix allows (a steward, by the standing
// rule) moves a DRAFT, OPEN or PENDING
// claim to another person (picked beside the move button); anyone else moving it, or moving a SETTLED or VOID claim,
// shows the claim's error. A steward voids a SETTLED claim within 7 days of its settlement (its frozen due leaves
// the totals); anyone else, or a later day, shows the claim's error. A steward re-settles a SETTLED claim at the figure it would have today as an open claim
// bound by no statement; anyone else, or any other status, shows the claim's error. An OPEN claim is deferred until
// a date after the sheet's today (typed beside the defer button); any other status, a date not after today, or a claim
// whose due-by is in a closed period shows the claim's error. A deferred claim cannot be settled. The proof button raises the claim's
// proofs count by one; on a SETTLED or VOID claim it shows the claim's error. A claim whose due is above the proof
// threshold in force on its date cannot be settled or approved while it has no proof: that shows the claim's error.
// An OPEN claim splits off an amount (typed beside the split button; more than 0.00 and less than its amount) into a
// new OPEN claim; any other status, a deferred claim, a claim whose due-by is in a closed period or an amount out of range shows the
// claim's error. A steward re-dates an OPEN or PENDING claim (the date typed beside the re-date button); anyone
// else, any other status, a claim whose due-by is in a closed period, or a new date after the person's retirement shows
// the claim's error. Re-dating keeps the due-by, so the claim keeps its period and number. An OPEN or PENDING claim is
// reminded once per sheet's today (its reminded date becomes today); a second press that day, or any other status, shows
// the claim's error.
function ClaimStatusActions({ sheet, claim, onEdit, editorSubmits, children }: {
  sheet: string; claim: Claim; onEdit: () => void; editorSubmits: number; children: ReactNode;
}) {
  const [user] = useCurrentUser();
  const queryClient = useQueryClient();
  const [reason, setReason] = useState('');
  const change = useMutation({
    mutationFn: ({ action, reason }: { action: string; reason?: string }) =>
      putJson<Claim>(`${claimsPath(sheet)}/${claim.id}/${action}`
        + (reason === undefined ? '' : `?reason=${encodeURIComponent(reason)}`), undefined, user),
    onSuccess: (_, { action }) => {
      if (action === 'reject') setReason('');
      return queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
    },
  });
  const submitChange = useSubmitOnce(change);
  const people = usePeople();
  const others = (people.data ?? []).filter((p) => p.id !== claim.personId);
  const [moveTo, setMoveTo] = useState('');
  const target = others.find((p) => String(p.id) === moveTo) ?? others[0];
  const move = useMutation({
    mutationFn: (personId: number) =>
      putJson<Claim>(`${claimsPath(sheet)}/${claim.id}/person/${personId}`, undefined, user),
    onSuccess: () => Promise.all([
      queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) }),
      queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet) }),
    ]),
  });
  const submitMove = useSubmitOnce(move);
  const today = useSheetToday();
  const [deferTo, setDeferTo] = useState('');
  const defer = useMutation({
    mutationFn: (until: string) =>
      putJson<Claim>(`${claimsPath(sheet)}/${claim.id}/defer?until=${encodeURIComponent(until)}`, undefined, user),
    onSuccess: () => {
      setDeferTo('');
      return queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
    },
  });
  const submitDefer = useSubmitOnce(defer);
  const [redateTo, setRedateTo] = useState('');
  const redate = useMutation({
    mutationFn: (date: string) =>
      putJson<Claim>(`${claimsPath(sheet)}/${claim.id}/redate?date=${encodeURIComponent(date)}`, undefined, user),
    onSuccess: () => {
